{
  "cli": {
    "version": ">= 16.0.1",
    "appVersionSource": "remote"
  },
  "build": {
    "development": {
      "developmentClient": true,
      "distribution": "internal"
    },
    "preview": {
      "distribution": "internal",
      "android": {
        "buildType": "apk"
      }
    },
    "production": {
      "autoIncrement": true,
      "distribution": "store",
      "android": {
        "buildType": "app-bundle"
      }
    }
  },
  "submit": {
    "production": {
      "ios": {
        // PLACEHOLDER: replace with the Apple ID (email) of the account that owns the App Store Connect app.
        "appleId": "REPLACE_WITH_APPLE_ID_EMAIL",
        // PLACEHOLDER: replace with the numeric App Store Connect app ID (App Store Connect > Tidy > App Information > Apple ID).
        "ascAppId": "REPLACE_WITH_ASC_APP_ID"
      },
      "android": {
        // PLACEHOLDER: place the Google Play service account JSON key at this path locally (or in CI). The secrets/ folder is gitignored.
        "serviceAccountKeyPath": "./secrets/google-play-service-account.json",
        "track": "production"
      }
    }
  }
}

